export type EvidenceOutcome = "review" | "recovered" | "independent";

export interface ConceptEvidence {
  conceptId: string;
  outcome: EvidenceOutcome;
  successes: number;
  lapses: number;
  lastReviewed: string;
  dueAt: string;
  source: "quiz" | "lab" | "review";
  itemId: string;
}

export const evidenceStorageKey = "linalg-concept-evidence-v1";

export function readEvidence(): Record<string, ConceptEvidence> {
  try {
    return JSON.parse(localStorage.getItem(evidenceStorageKey) || "{}") as Record<string, ConceptEvidence>;
  } catch {
    return {};
  }
}

export function recordConceptEvidence(
  conceptIds: string[],
  outcome: EvidenceOutcome,
  source: ConceptEvidence["source"],
  itemId: string,
): void {
  if (!conceptIds.length) return;
  const evidence = readEvidence();
  const now = new Date();
  for (const conceptId of conceptIds) {
    const previous = evidence[conceptId];
    const successes = (previous?.successes || 0) + (outcome === "review" ? 0 : 1);
    const lapses = (previous?.lapses || 0) + (outcome === "review" ? 1 : 0);
    const delayDays = outcome === "review" ? 0 : outcome === "recovered" ? 3 : successes >= 2 ? 21 : 7;
    evidence[conceptId] = {
      conceptId,
      outcome,
      successes,
      lapses,
      lastReviewed: now.toISOString(),
      dueAt: new Date(now.getTime() + delayDays * 86_400_000).toISOString(),
      source,
      itemId,
    };
  }
  try { localStorage.setItem(evidenceStorageKey, JSON.stringify(evidence)); } catch { /* learning remains usable without storage */ }
  window.dispatchEvent(new CustomEvent("linalg-evidence-updated"));
}
